refentry.refsect1:
  &reftitle.examples;

   Time\Duration::compare example


<?php
$a = Time\Duration::fromSeconds(1);
$b = Time\Duration::fromMilliseconds(1500);

var_dump(Time\Duration::compare($a, $b));
var_dump(Time\Duration::compare($b, $a));
var_dump(Time\Duration::compare($a, Time\Duration::fromNanoseconds(1_000_000_000)));

// Negative durations are smaller than positive ones.
var_dump(Time\Duration::compare($a->negate(), $a));


   &example.outputs;


int(-1)
int(1)
int(0)
int(-1)




   Sorting durations with Time\Duration::compare


<?php
$durations = [
    Time\Duration::fromMinutes(2),
    Time\Duration::fromMilliseconds(250),
    Time\Duration::fromSeconds(5),
];

usort($durations, Time\Duration::compare(...));

foreach ($durations as $duration) {
    printf("%d.%09d\n", $duration->seconds, $duration->nanoseconds);
}


   &example.outputs;


0.250000000
5.000000000
120.000000000
